V.history=()=>`<div class="panel"><h3>Opérations</h3><input id="hq" placeholder="🔍 Rechercher une opération" value="${esc(HF.q)}"><div class="pk" style="margin:10px 0">${[['','Toutes'],['in','Reçues'],['out','Émises']].map(([k,l])=>`<button class="${HF.t==k?'on':''}" data-act="hf" data-k="${k}">${l}</button>`).join('')}</div><div id="hl">${hlist()}</div></div>`;
V.home=()=>{const fn=me.name.split(' ')[0],s=t=>me.txs.filter(x=>x.t==t&&x.mode!='int').reduce((a,x)=>a+x.a,0),i=s('in'),o=s('out'),m=Math.max(i,o,1);
return `<div class="hello"><h2>Bonjour ${esc(fn)} 👋</h2><div class="iban">${me.prev?'Dernière connexion : '+fd(me.prev):'Première connexion'} · N° client ${me.cn}</div></div><div class="grid"><div class="panel"><h3>Mes comptes</h3><div class="acc" data-act="go" data-v="history"><div class="ai">🏦</div><div class="ad"><b>Compte courant</b><div class="iban">${spc(me.iban)}</div></div><div class="ab">${E(me.bal)}</div></div><div class="acc" data-act="sav"><div class="ai">🐷</div><div class="ad"><b>Livret A</b><div class="iban">Versements et retraits manuels</div></div><div class="ab">${E(me.sav||0)}</div></div><div class="iban">BIC NOVAFRPP · NovaBank SA</div><div class="qa"><button class="btn sm" data-act="go" data-v="transfer">💸 Virement</button><button class="btn sm ghost" data-act="go" data-v="contacts">👥 Contacts</button><button class="btn sm ghost" data-act="rib">🏦 RIB</button><button class="btn sm ghost" data-act="go" data-v="cards">💳 Carte</button></div></div><div class="panel hero"><div id="c3d" class="c3d"></div></div><div class="panel"><h3>Budget</h3><div class="bar"><span>Entrées</span><div><i style="width:${i/m*100}%;background:var(--ok)"></i></div><b>${E(i)}</b></div><div class="bar"><span>Sorties</span><div><i style="width:${o/m*100}%;background:var(--ko)"></i></div><b>${E(o)}</b></div></div><div class="panel"><h3>Dernières opérations</h3>${list(me.txs.slice(0,6),1)}</div></div>`};
function csr(q){q=(q||'').trim().toLowerCase();const nq=N(q),r=all().filter(x=>x!==me&&!me.contacts.includes(x.iban)&&(!q||x.name.toLowerCase().includes(q)||(x.user||'').toLowerCase().includes(q)||(nq.length>=4&&(N(x.iban).includes(nq)||N(x.pan).includes(nq))))).slice(0,8);return r.length?r.map(p=>`<div class="crow"><div class="av" style="margin:0">${avt(p)}</div><div class="ci"><b>${esc(p.name)}</b><div class="iban">${p.user?'@'+esc(p.user)+' · ':''}…${p.iban.slice(-4)}${p.shop?' · 🛍️ '+esc(p.shop.name):''}</div></div><button class="btn sm" data-act="addp" data-iban="${p.iban}">Ajouter</button></div>`).join(''):'<div class="empty">Aucun membre trouvé : ce compte n\'existe pas chez NovaBank.</div>'}
V.contacts=()=>`<div class="panel"><div style="display:flex;justify-content:space-between;align-items:center;gap:10px;margin-bottom:10px"><h3 style="margin:0">Mes contacts (${me.contacts.length})</h3><button class="btn sm" data-act="addm">＋ Ajouter un contact</button></div>${me.contacts.length?me.contacts.map((c,i)=>{const p=byI(c);if(!p)return'';const m=cm(p);return `<div class="crow" data-act="prof" data-i="${i}"><div class="av" style="margin:0">${avt(p)}</div><div class="ci"><b>${m.fav?'⭐ ':''}${esc(dn(p))}</b><div class="iban">${m.nick?esc(p.name)+' · ':''}…${p.iban.slice(-4)}${p.shop?' · 🛍️ '+esc(p.shop.name):''}</div>${m.note?`<div class="iban" style="font-style:italic">📝 ${esc(m.note)}</div>`:''}</div><span class="iban">›</span></div>`}).join(''):'<div class="empty">Aucun contact. Ajoute un membre NovaBank pour lui envoyer de l\'argent ou voir sa boutique.</div>'}</div>`;
function showProf(p){const m=cm(p),s=p.shop,sx=me.txs.filter(t=>t.n==p.name&&t.mode!='int'),so=sx.filter(t=>t.t=='out').reduce((a,t)=>a+t.a,0),si=sx.filter(t=>t.t=='in').reduce((a,t)=>a+t.a,0);TI={};
modal(`<label class="pf" for="cpi"><div class="av big">${avt(p)}</div><span>📷 Modifier la photo</span></label><input id="cpi" type="file" accept="image/*" hidden><img id="cpiv" class="upv" style="max-height:90px;width:90px;border-radius:50%;margin:6px auto 0"><h2 style="text-align:center;margin-top:8px">${esc(dn(p))}</h2><p style="text-align:center">${m.nick?esc(p.name)+' · ':''}Client NovaBank vérifié ✔ · …${p.iban.slice(-4)}</p><div class="stat"><div>Envoyé<b>${E(so)}</b></div><div>Reçu<b>${E(si)}</b></div><div>Opérations<b>${sx.length}</b></div></div><label>Surnom</label><input id="cn" maxlength="24" value="${esc(m.nick||'')}" placeholder="Ex : Bro, Maman…"><label>Note personnelle</label><textarea id="cnt" rows="2" maxlength="160" placeholder="Visible par toi uniquement">${esc(m.note||'')}</textarea><div class="actions"><button class="btn sm" data-act="csave" data-iban="${p.iban}">💾 Enregistrer</button><button class="btn sm ghost" data-act="cfav" data-iban="${p.iban}">${m.fav?'★ Retirer des favoris':'☆ Favori'}</button>${m.pic?`<button class="btn sm ghost" data-act="cprm" data-iban="${p.iban}">Retirer la photo</button>`:''}</div>${s?`<h3 style="margin:20px 0 10px">🛍️ Sa boutique</h3><div class="found" style="display:block;cursor:pointer" data-act="site" data-iban="${p.iban}">${cov(s)}<b style="display:block;margin-top:10px">${esc(s.name)}</b><div class="iban">🌐 ${site(s)}</div><div class="iban">${esc(s.desc||'')}</div><div class="its" style="grid-template-columns:repeat(auto-fill,minmax(80px,1fr));margin-top:10px">${s.items.slice(0,4).map(it=>`<div class="it" style="padding:6px">${pic(it)}<small>${E(it.price)}</small></div>`).join('')}</div><div class="btn sm" style="display:inline-block;margin-top:10px">Visiter la boutique →</div></div>`:'<p style="margin-top:14px" class="iban">Ce contact n\'a pas encore de boutique.</p>'}<h3 style="margin:20px 0 6px">Opérations récentes</h3>${list(sx.slice(0,4))}<button class="btn" data-act="tgo" data-iban="${p.iban}">💸 Envoyer de l'argent</button><button class="btn ghost" style="width:100%;margin-top:10px" data-act="crem" data-iban="${p.iban}">Retirer ce contact</button>`,560)}
document.addEventListener('input',e=>{if(e.target.id=='cs'){const c=$('#cres');if(c)c.innerHTML=csr(e.target.value)}if(e.target.id=='hq'){HF.q=e.target.value;const h=$('#hl');if(h)h.innerHTML=hlist()}});
const DEMO={name:'VOTRE NOM',pan:'4970123456789012',cvv:'123',col:'violet',net:'visa',frozen:0};
const BG=(()=>{try{if(!window.THREE)throw 0;
const cv=document.createElement('canvas');cv.id='bg3d';document.body.prepend(cv);
const r=new THREE.WebGLRenderer({canvas:cv,antialias:true,alpha:true});r.setPixelRatio(Math.min(devicePixelRatio,1.5));r.outputEncoding=THREE.sRGBEncoding;r.toneMapping=THREE.ACESFilmicToneMapping;r.toneMappingExposure=1.1;
const sc=new THREE.Scene(),cam=new THREE.PerspectiveCamera(50,1,.1,100);cam.position.z=12;
const en=new THREE.Scene();en.background=new THREE.Color(0x1c2234);[[0,4,3,6,2,0xffffff,14],[-5,0,2,2,5,0x88aaff,7],[5,-1,2,2,5,0xffb3e6,6]].forEach(([X,Y,Z,w,h,c,i])=>{const m=new THREE.Mesh(new THREE.PlaneGeometry(w,h),new THREE.MeshBasicMaterial({color:new THREE.Color(c).multiplyScalar(i),side:2}));m.position.set(X,Y,Z);m.lookAt(0,0,0);en.add(m)});
sc.environment=new THREE.PMREMGenerator(r).fromScene(en,.04).texture;
const k=document.createElement('canvas');k.width=k.height=256;const x=k.getContext('2d'),g=x.createRadialGradient(128,100,10,128,128,128);g.addColorStop(0,'#fff0a8');g.addColorStop(1,'#c9962b');x.fillStyle=g;x.fillRect(0,0,256,256);x.strokeStyle='#8a5f10';x.lineWidth=10;x.beginPath();x.arc(128,128,100,0,7);x.stroke();x.fillStyle='#8a5f10';x.font='bold 150px Georgia,serif';x.textAlign='center';x.textBaseline='middle';x.fillText('\u20ac',128,138);
const t=new THREE.CanvasTexture(k);t.encoding=THREE.sRGBEncoding;
const cap=new THREE.MeshStandardMaterial({map:t,metalness:1,roughness:.3}),sd=new THREE.MeshStandardMaterial({color:0xc99a2e,metalness:1,roughness:.28}),geo=new THREE.CylinderGeometry(.5,.5,.1,48);
const coin=s=>{const m=new THREE.Mesh(geo,[sd,cap,cap]);m.scale.setScalar(s);m.rotation.set(Math.random()*6,Math.random()*6,0);sc.add(m);return m},rn=(a,b)=>a+Math.random()*(b-a);
const F=[],n=innerWidth<700?20:60;
for(let i=0;i<n;i++){const m=coin(rn(.5,1.1));m.position.set(rn(-15,15),rn(-9,9),rn(-16,2));F.push({m,ry:rn(.004,.015),rx:rn(.002,.01),ph:rn(0,6),y:m.position.y})}
const S=[0x6c5ce7,0x00cec9,0xff7ab8].flatMap(c=>[0,1,2].map(()=>{const m=new THREE.Mesh(new THREE.SphereGeometry(rn(.3,.8),32,24),new THREE.MeshPhysicalMaterial({color:c,metalness:.1,roughness:.05,clearcoat:1,transparent:true,opacity:.5}));m.position.set(rn(-14,14),rn(-8,8),rn(-14,0));sc.add(m);return{m,ph:rn(0,6),y:m.position.y}}));
const B=[];let mx=0,my=0,sy=0,tt=0;const grid=new THREE.GridHelper(80,40,0x6c5ce7,0x2b3470);grid.position.y=-10;sc.add(grid);const tor=new THREE.Mesh(new THREE.TorusKnotGeometry(2.2,.5,160,24),new THREE.MeshPhysicalMaterial({color:0x7a6cff,metalness:.9,roughness:.15,clearcoat:1}));tor.position.set(9,3,-12);sc.add(tor);const stars=new THREE.Points(new THREE.BufferGeometry().setAttribute('position',new THREE.Float32BufferAttribute(Array.from({length:900},()=>rn(-40,40)),3)),new THREE.PointsMaterial({color:0xffffff,size:.08}));sc.add(stars);
addEventListener('mousemove',e=>{mx=e.clientX/innerWidth-.5;my=e.clientY/innerHeight-.5});addEventListener('scroll',()=>sy=scrollY,{passive:true});
function rs(){r.setSize(innerWidth,innerHeight,false);cam.aspect=innerWidth/innerHeight;cam.updateProjectionMatrix()}addEventListener('resize',rs);rs();
(function lp(){requestAnimationFrame(lp);tt+=.01;tor.rotation.x+=.004;tor.rotation.y+=.006;grid.position.z=(tt*3)%2;stars.rotation.y+=.0004;
 F.forEach(o=>{o.m.rotation.y+=o.ry;o.m.rotation.x+=o.rx;o.m.position.y=o.y+Math.sin(tt+o.ph)*.5});
 S.forEach(o=>o.m.position.y=o.y+Math.sin(tt*.8+o.ph)*.6);
 for(let i=B.length-1;i>=0;i--){const b=B[i];if(b.fly){b.t++;const p=b.t/80;b.m.position.set(-6+12*p,-3+4*p+Math.sin(p*Math.PI)*3.5,3-2*p);b.m.rotation.y+=.3;b.m.rotation.x+=.1;if(p>=1){sc.remove(b.m);B.splice(i,1)}}else{b.vy-=.012;b.m.position.x+=b.vx;b.m.position.y+=b.vy;b.m.position.z+=b.vz;b.m.rotation.x+=b.rx;b.m.rotation.y+=b.ry;if(b.m.position.y<-11){sc.remove(b.m);B.splice(i,1)}}}
 cam.position.x+=(mx*3-cam.position.x)*.04;cam.position.y+=(-my*2-sy*.004-cam.position.y)*.04;cam.lookAt(0,-sy*.002,0);r.render(sc,cam)})();
return{burst(c){for(let i=0;i<c;i++){const m=coin(rn(.4,.8));m.position.set(rn(-8,8),rn(9,14),rn(-3,5));B.push({m,vx:rn(-.02,.02),vy:rn(-.1,0),vz:rn(-.01,.03),rx:rn(.05,.2),ry:rn(.05,.2)})}},fly(){const m=coin(.9);m.position.set(-6,-3,3);B.push({m,fly:1,t:0})}}}catch(e){return{burst(){},fly(){}}}})();
if(DB.s&&DB.users[DB.s])login(DB.s);else mount3d($('#c3a'),DEMO);
